<script>
import PageHero from "@/components/PageHero.vue";
import logo from "@/assets/exshipsLogo.webp";
import { members } from "@/constants/members";
import { blogPosts } from "@/constants/blogPosts";
import { snsLinks } from "@/constants/snsLinks";
import { formatDotDate } from "@/utils/date";
import { vReveal } from "@/composables/useScrollReveal";

// 各メンバーのカードに載せる執筆記事の件数
const POSTS_PER_MEMBER = 2;

export default {
  name: "CompanyProfile",
  components: { PageHero },
  directives: { reveal: vReveal },
  data: () => ({
    pageVisible: false,
    logo,
    members,
    companyInfo: [
      {
        icon: "mdi-office-building",
        title: "企業名",
        subtitle: "Company Name",
        text: "合同会社エクスシップス",
        accent: true,
      },
      {
        icon: "mdi-account-tie",
        title: "代表社員",
        subtitle: "Representative Member",
        text: "小塚 啓太",
        accent: false,
      },
      {
        icon: "mdi-calendar",
        title: "設立",
        subtitle: "Established",
        text: "2020年1月6日",
        accent: true,
      },
      {
        icon: "mdi-currency-jpy",
        title: "資本金",
        subtitle: "Capital",
        text: "1,000,000円",
        accent: false,
      },
      {
        icon: "mdi-briefcase",
        title: "事業内容",
        subtitle: "Business",
        text: "スマートフォン向けアプリケーション開発<br>DevOps・アジャイル開発推進事業<br>Webサイト制作",
        accent: true,
      },
      {
        icon: "mdi-map-marker",
        title: "本社所在地",
        subtitle: "Registered Office",
        text: "〒145-0066<br>東京都大田区南雪谷1-5-5 ROOM D",
        accent: false,
      },
      {
        icon: "mdi-file-certificate",
        title: "顧問税理士",
        subtitle: "Tax Accountant",
        text: "東京税理士会 雪谷支部<br>髙木淳公認会計士・税理士事務所",
        accent: true,
      },
    ],
  }),
  computed: {
    // 著者名で絞った最新記事（HomeView のお知らせと同じ日付降順）
    postsByAuthor() {
      const sorted = [...blogPosts].sort((a, b) =>
        (b.date || "").localeCompare(a.date || "")
      );
      return Object.fromEntries(
        this.members.map((m) => [
          m.id,
          sorted
            .filter((p) => p.author && p.author.name === m.authorName)
            .slice(0, POSTS_PER_MEMBER),
        ])
      );
    },
  },
  mounted() {
    setTimeout(() => (this.pageVisible = true), 200);
  },
  methods: {
    formatDotDate,
    // snsLinks の定義（URL・ロゴ・ブランド色）に、カード用の label を重ねる
    snsFor(member) {
      return member.sns
        .map((ref) => ({ ...snsLinks.find((l) => l.id === ref.id), ...ref }))
        .filter((l) => l.href);
    },
  },
};
</script>

